export function paintShadowTriangles(ctx,data,proj,alpha=1,color='#15202e'){const c=rgb(color).map(v=>Math.round(v*255)).join(',');ctx.globalAlpha=alpha;for(let i=0;i<data.length;i+=27){const qs=[0,9,18].map(k=>proj([data[i+k],data[i+k+1],data[i+k+2]]));if(qs.some(p=>!p.visible))continue;const [a,b,d]=qs,aa=data[i+6],ab=data[i+15],ad=data[i+24],den=(b.x-a.x)*(d.y-a.y)-(d.x-a.x)*(b.y-a.y);if(Math.abs(den)<.001)continue;const gx=((ab-aa)*(d.y-a.y)-(ad-aa)*(b.y-a.y))/den,gy=((b.x-a.x)*(ad-aa)-(d.x-a.x)*(ab-aa))/den,g2=gx*gx+gy*gy;if(g2<1e-10)ctx.fillStyle=`rgba(${c},${aa})`;else{const x=a.x-aa*gx/g2,y=a.y-aa*gy/g2,gradient=ctx.createLinearGradient(x,y,x+gx/g2,y+gy/g2);gradient.addColorStop(0,`rgba(${c},0)`);gradient.addColorStop(1,`rgba(${c},1)`);ctx.fillStyle=gradient}ctx.beginPath();qs.forEach((q,j)=>j?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.closePath();ctx.fill()}ctx.globalAlpha=1}

export function paintNativeGeometry(ctx,data,m,view,alpha=1){const tris=[];for(let i=0;i<data.length;i+=27){const ps=[0,9,18].map(k=>localPoint(m,[data[i+k],data[i+k+1],data[i+k+2]])),qs=ps.map(p=>project(view.vp,p,view.W,view.H));if(qs.some(q=>!q.visible))continue;tris.push({qs,depth:ps.reduce((v,p)=>v+Math.hypot(...sub(p,view.camera.eye)),0),color:`rgb(${[6,7,8].map(k=>Math.round(data[i+k]*255)).join(',')})`})}tris.sort((a,b)=>b.depth-a.depth);ctx.globalAlpha=alpha;for(const t of tris){ctx.fillStyle=t.color;ctx.beginPath();t.qs.forEach((q,j)=>j?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.closePath();ctx.fill()}ctx.globalAlpha=1}
